//! Embedded SVG icons (Lucide, ISC license) served through GPUI's `AssetSource`.

use anyhow::Result;
use gpui::{AssetSource, SharedString};
use std::borrow::Cow;

pub struct Assets;

macro_rules! icons {
    ($($name:literal => $svg:literal),* $(,)?) => {
        fn lookup(path: &str) -> Option<&'static [u8]> {
            match path {
                $( concat!("icons/", $name, ".svg") => Some($svg.as_bytes()), )*
                _ => None,
            }
        }
        const ICON_NAMES: &[&str] = &[$( concat!("icons/", $name, ".svg") ),*];
    };
}

